import crossSpawn from 'cross-spawn';
export const spawn = {
    sync: (bin, args, options) => {
        const result = crossSpawn.sync(bin, args, options);
        if (result.error)
            throw result.error;
        if (result.status !== 0) {
            throw new Error(`Command failed (exit code ${result.status}): ${bin} ${args.join(' ')}`);
        }
    },
};
